    const fileSizeLabel=value=>{const bytes=Number(value)||0;if(bytes<1024)return bytes+' B';if(bytes<1024*1024)return(bytes/1024).toFixed(bytes<10240?1:0)+' KB';return(bytes/1024/1024).toFixed(1)+' MB'};
    const isPdfAttachment=file=>String(file?.contentType||'').toLowerCase()==='application/pdf';
    function noteAttachmentList(noteId,removable=false){const files=noteAttachmentsFor(noteId);return '<section class="note-attachments"><h3>Documentos adjuntos <span>'+files.length+' '+(files.length===1?'archivo':'archivos')+'</span></h3>'+(files.length?'<div class="note-attachment-list">'+files.map(file=>{const pdf=isPdfAttachment(file),url='/api/permanent-note-attachments/'+file.id;return'<article class="note-attachment"><span class="note-attachment-icon '+(pdf?'pdf':'')+'">'+(pdf?'PDF':'▤')+'</span><div class="note-attachment-copy"><b>'+esc(file.fileName)+'</b><small>'+fileSizeLabel(file.sizeBytes)+' · '+fmt(file.createdAt,true)+'</small></div><div class="note-attachment-actions">'+(pdf?'<button type="button" class="pdf-read-button" data-view-pdf-attachment="'+file.id+'">Leer PDF</button>':'<a href="'+url+'" target="_blank" rel="noopener">Abrir</a>')+'<a href="'+url+'?download=1">Descargar</a>'+(removable?'<button type="button" data-delete-note-attachment="'+file.id+'" data-note-id="'+noteId+'">Eliminar</button>':'')+'</div></article>'}).join('')+'</div>':'<p class="note-attachment-empty">Esta nota todavía no tiene documentos.</p>')+'</section>'}
    function noteFileInput(){return '<label class="field note-file-field">Adjuntar documentos <small>(opcional)</small><input name="files" type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv,.png,.jpg,.jpeg,.webp"><small>Puedes guardar solo documentos, sin escribir una anotación. Hasta 5 archivos por subida y 10 MB por archivo.</small></label>'}
    function validNoteFiles(input){const files=[...(input?.files||[])];if(files.length>5){toast('Puedes adjuntar un máximo de 5 documentos cada vez.');return null}if(files.some(file=>file.size>10*1024*1024)){toast('Cada documento debe ocupar 10 MB o menos.');return null}return files}
    async function uploadNoteFiles(noteId,files){if(!files.length)return{ok:true};const body=new FormData();body.set('noteId',String(noteId));files.forEach(file=>body.append('files',file,file.name));state.saving=true;try{const response=await fetch('/api/permanent-note-attachments',{method:'POST',body}),data=await response.json();if(!response.ok)throw Error(data.error);state.data=data;render();return{ok:true}}catch(error){return{ok:false,error:error?.message||'No se pudieron adjuntar los documentos.'}}finally{state.saving=false}}
    async function savePermanentNoteWithFiles(payload,fileInput){const files=validNoteFiles(fileInput);if(files===null)return false;const content=String(payload.content||'').trim(),existingFiles=payload.id?noteAttachmentsFor(payload.id).length:0;if(!content&&!files.length&&!existingFiles){toast('Escribe una anotación o adjunta al menos un documento.');return false}payload={...payload,content,hasFiles:Boolean(files.length||existingFiles)};const result=await send(payload);if(!result)return false;const noteId=Number(result.savedNoteId||payload.id);if(files.length){const uploaded=await uploadNoteFiles(noteId,files);if(!uploaded.ok){if(!payload.id&&!content){await send({action:'delete_permanent_note',id:noteId});toast(uploaded.error+' La nota vacía no se ha guardado.');return false}toast(uploaded.error+' El texto de la nota sí se ha guardado.');return'partial'}}return true}
    function openPdfAttachment(id,returnTo='view'){const file=(state.data.permanentNoteAttachments||[]).find(x=>Number(x.id)===Number(id));if(!file||!isPdfAttachment(file))return;const noteId=Number(file.noteId),close=()=>returnTo==='edit'?noteEditor(noteId):viewNote(noteId),url='/api/permanent-note-attachments/'+file.id;overlay.innerHTML='<div class="backdrop pdf-backdrop"><section class="pdf-viewer" role="dialog" aria-modal="true" aria-labelledby="pdf-viewer-title"><header class="pdf-viewer-head"><span class="pdf-viewer-icon">PDF</span><div class="pdf-viewer-copy"><b id="pdf-viewer-title">'+esc(file.fileName)+'</b><small>'+fileSizeLabel(file.sizeBytes)+' · visor de lectura</small></div><div class="pdf-viewer-actions"><a href="'+url+'" target="_blank" rel="noopener">↗ Abrir aparte</a><a href="'+url+'?download=1">⇩ Descargar</a><button class="icon-btn" type="button" data-close-pdf aria-label="Cerrar visor">×</button></div></header><div class="pdf-viewer-frame-wrap"><iframe class="pdf-viewer-frame" src="'+url+'#toolbar=1&navpanes=0&view=FitH" title="Leer '+esc(file.fileName)+'"></iframe></div></section></div>';overlay.querySelector('[data-close-pdf]').onclick=close;overlay.querySelector('.pdf-backdrop').onclick=e=>{if(e.target===e.currentTarget)close()}}
    function bindPdfAttachments(returnTo){overlay.querySelectorAll('[data-view-pdf-attachment]').forEach(button=>button.onclick=()=>openPdfAttachment(Number(button.dataset.viewPdfAttachment),returnTo))}
    function permanentNoteCard(note){const archived=Boolean(note.archivedAt),fileCount=noteAttachmentsFor(note.id).length,content=String(note.content||'').trim();return '<article class="permanent-note '+(archived?'archived':'')+'"><div class="permanent-note-head"><div class="permanent-note-title"><i>'+(archived?'▣':'∞')+'</i><h3>'+esc(note.title||'Nota permanente')+'</h3></div><div class="permanent-note-actions"><button data-view-permanent-note="'+note.id+'" aria-label="Consultar nota y documentos" title="Consultar">◉</button>'+(archived?'<button data-archive-permanent-note="'+note.id+'" data-archived="false" aria-label="Restaurar nota" title="Restaurar">↺</button>':'<button data-edit-permanent-note="'+note.id+'" aria-label="Editar nota" title="Editar">✎</button><button data-archive-permanent-note="'+note.id+'" data-archived="true" aria-label="Archivar nota" title="Archivar">▣</button>')+'<button data-delete-permanent-note="'+note.id+'" aria-label="Eliminar nota" title="Eliminar">⌫</button></div></div>'+(content?'<p>'+esc(content)+'</p>':'<p class="note-document-only">Nota guardada solo con documentos.</p>')+(fileCount?'<span class="note-doc-count">▤ '+fileCount+' '+(fileCount===1?'documento':'documentos')+'</span>':'')+'<small>'+(archived?'Archivada · '+fmt(note.archivedAt,true):'Actualizada · '+fmt(note.updatedAt,true))+'</small></article>'}
    function notePostit(note){const edited=String(note.updatedAt)!==String(note.createdAt),archived=Boolean(note.archivedAt),fileCount=noteAttachmentsFor(note.id).length,content=String(note.content||'').trim();return '<article class="postit tone-'+(Number(note.id)%5)+' '+(archived?'archived':'')+'"><span class="postit-pin"></span><div class="postit-head"><h3>'+esc(note.title||'Nota sin título')+'</h3><div class="postit-actions"><button data-view-note="'+note.id+'" aria-label="Consultar nota" title="Consultar">◉</button>'+(archived?'<button data-archive-permanent-note="'+note.id+'" data-archived="false" aria-label="Restaurar nota" title="Restaurar">↺</button>':'<button data-edit-note="'+note.id+'" aria-label="Editar nota" title="Editar">✎</button><button data-archive-permanent-note="'+note.id+'" data-archived="true" aria-label="Archivar nota" title="Archivar">▣</button>')+'<button class="postit-delete" data-delete-note="'+note.id+'" aria-label="Eliminar nota" title="Eliminar">⌫</button></div></div><p class="postit-content">'+esc(content||'Nota guardada solo con documentos.')+'</p>'+(fileCount?'<span class="note-doc-count">▤ '+fileCount+' '+(fileCount===1?'documento':'documentos')+'</span>':'')+'<div class="postit-meta"><b>'+(archived?'Archivada · '+fmt(note.archivedAt,true):'Creada · '+fmt(note.createdAt,true))+'</b>'+(!archived&&edited?'<span>Editada · '+fmt(note.updatedAt,true)+'</span>':'')+'</div></article>'}
    async function setPermanentNoteArchived(id,archived){if(await send({action:'archive_permanent_note',id,archived})){toast(archived?'Nota archivada.':'Nota restaurada.')}}
    function bindPermanentNoteArchive(){app.querySelectorAll('[data-note-archive-tab]').forEach(b=>b.onclick=()=>{state.noteArchiveTab=b.dataset.noteArchiveTab;render()});app.querySelectorAll('[data-archive-permanent-note]').forEach(b=>b.onclick=()=>setPermanentNoteArchived(Number(b.dataset.archivePermanentNote),b.dataset.archived==='true'))}
    function renderNotes(){const all=(state.data.permanentNotes||[]).slice(),activeNotes=all.filter(x=>!x.archivedAt),archivedNotes=all.filter(x=>x.archivedAt),notes=(state.noteArchiveTab==='archived'?archivedNotes:activeNotes).sort((a,b)=>String(state.noteArchiveTab==='archived'?b.archivedAt:b.updatedAt).localeCompare(String(state.noteArchiveTab==='archived'?a.archivedAt:a.updatedAt))||Number(b.id)-Number(a.id)),archived=state.noteArchiveTab==='archived';app.innerHTML='<header class="page-head notes-page-head"><div><small>TU TABLÓN PERSONAL</small><h1>Notas</h1><p>Apuntes rápidos guardados con su día y hora, siempre listos para consultar.</p></div><button class="primary" data-new-note>＋ Nueva nota</button></header><section class="notes-board-shell"><div class="notes-board-head"><div><h2>'+(archived?'Notas archivadas':'Mis pósits')+'</h2><p>'+(archived?'Consúltalas o restáuralas cuando vuelvan a ser útiles.':'Las notas editadas se colocan primero para que encuentres rápido lo más reciente.')+'</p></div><div class="note-archive-tabs"><button class="'+(!archived?'on':'')+'" data-note-archive-tab="active">Activas · '+activeNotes.length+'</button><button class="'+(archived?'on':'')+'" data-note-archive-tab="archived">Archivadas · '+archivedNotes.length+'</button></div></div>'+(notes.length?'<div class="postit-grid">'+notes.map(notePostit).join('')+'</div>':'<div class="notes-empty"><div><span>'+(archived?'▣':'▰')+'</span><h2>'+(archived?'No tienes notas archivadas':'Tu tablón está vacío')+'</h2><p>'+(archived?'Cuando archives una nota, podrás consultarla aquí.':'Crea un pósit para guardar una idea, un dato o cualquier apunte rápido.')+'</p>'+(!archived?'<button class="primary" data-new-note>＋ Crear primera nota</button>':'')+'</div></div>')+'</section>';app.querySelectorAll('[data-new-note]').forEach(b=>b.onclick=()=>noteEditor());app.querySelectorAll('[data-view-note]').forEach(b=>b.onclick=()=>viewNote(Number(b.dataset.viewNote)));app.querySelectorAll('[data-edit-note]').forEach(b=>b.onclick=()=>noteEditor(Number(b.dataset.editNote)));app.querySelectorAll('[data-delete-note]').forEach(b=>b.onclick=()=>confirmDeletePermanentNote(Number(b.dataset.deleteNote)));bindPermanentNoteArchive()}
    function viewNote(id){const note=(state.data.permanentNotes||[]).find(x=>Number(x.id)===Number(id));if(!note)return;const archived=Boolean(note.archivedAt),content=String(note.content||'').trim();overlay.innerHTML='<div class="backdrop"><section class="note-readonly" role="dialog" aria-modal="true" aria-labelledby="note-readonly-title"><div class="note-readonly-head"><div><small>'+(archived?'▣ NOTA ARCHIVADA':'▰ NOTA GUARDADA')+'</small><h2 id="note-readonly-title">'+esc(note.title||'Nota sin título')+'</h2></div><button class="icon-btn" data-close aria-label="Cerrar">×</button></div><div class="note-readonly-body">'+(content?'<p>'+esc(content)+'</p>':'<p class="note-document-only">Esta nota se ha guardado como documento, sin texto adicional.</p>')+noteAttachmentList(id,false)+'<div class="note-readonly-dates"><div><small>CREADA</small><b>'+fmt(note.createdAt,true)+'</b></div><div><small>'+(archived?'ARCHIVADA':'ÚLTIMA MODIFICACIÓN')+'</small><b>'+fmt(archived?note.archivedAt:note.updatedAt,true)+'</b></div></div></div><div class="note-readonly-footer"><button class="secondary" data-close>Cerrar</button><button class="primary" '+(archived?'data-restore-view-note':'data-edit-view-note')+'>'+(archived?'↺ Restaurar nota':'✎ Editar nota')+'</button></div></section></div>';overlay.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>overlay.innerHTML='');overlay.querySelector('.backdrop').onclick=e=>{if(e.target===e.currentTarget)overlay.innerHTML=''};bindPdfAttachments('view');if(archived)overlay.querySelector('[data-restore-view-note]').onclick=async()=>{overlay.innerHTML='';await setPermanentNoteArchived(id,false)};else overlay.querySelector('[data-edit-view-note]').onclick=()=>noteEditor(id)}
    function noteEditor(id=0){const note=id?(state.data.permanentNotes||[]).find(x=>Number(x.id)===Number(id)):null;if(id&&!note)return;overlay.innerHTML='<div class="backdrop"><section class="modal" style="max-width:620px"><div class="modal-head"><div><b class="modal-icon">▰</b><span><h2>'+(note?'Editar nota':'Nueva nota')+'</h2><p>Guarda texto, documentos o ambas cosas para consultarlos cuando los necesites.</p></span></div><button class="icon-btn" data-close>×</button></div><form id="note-editor-form"><div class="form"><label class="field">Título <small>(opcional)</small><input name="title" maxlength="100" placeholder="Ej. Idea para la próxima reunión" value="'+esc(note?.title||'')+'"></label><label class="field">Nota <small>(opcional si adjuntas un documento)</small><textarea name="content" maxlength="5000" rows="9" placeholder="Puedes escribir un apunte o dejarlo vacío si adjuntas un archivo.">'+esc(note?.content||'')+'</textarea><small>Máximo 5.000 caracteres.</small></label>'+noteFileInput()+(note?noteAttachmentList(id,true):'')+'</div><div class="actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary">'+(note?'Guardar cambios':'Guardar nota')+'</button></div></form></section></div>';overlay.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>overlay.innerHTML='');overlay.querySelector('.backdrop').onclick=e=>{if(e.target===e.currentTarget)overlay.innerHTML=''};bindPdfAttachments('edit');overlay.querySelectorAll('[data-delete-note-attachment]').forEach(b=>b.onclick=async()=>{b.disabled=true;if(await send({action:'delete_permanent_note_attachment',id:Number(b.dataset.deleteNoteAttachment)})){toast('Documento eliminado.');noteEditor(Number(b.dataset.noteId))}else b.disabled=false});const form=overlay.querySelector('#note-editor-form'),input=form.querySelector('textarea'),button=form.querySelector('.primary'),fileInput=form.querySelector('input[type=file]');input.focus();let submitting=false;form.onsubmit=async e=>{e.preventDefault();if(submitting)return;const fd=new FormData(form),content=String(fd.get('content')||'').trim();submitting=true;button.disabled=true;button.textContent='Guardando…';const saved=await savePermanentNoteWithFiles({action:'save_permanent_note',id,title:fd.get('title'),content},fileInput);if(saved){overlay.innerHTML='';if(saved===true)toast(note?'Nota y documentos actualizados.':'Nota guardada con sus documentos.')}else{submitting=false;button.disabled=false;button.textContent=note?'Guardar cambios':'Guardar nota'}}}
    function renderDatedReminders(){const pending=state.data.reminders.filter(r=>!r.isDone).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),done=state.data.reminders.filter(r=>r.isDone).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt)));return '<div class="reminders-layout"><form class="reminder-compose" id="reminder-form"><div class="reminder-section-title"><b>◷</b><div><h2>Nuevo recordatorio</h2><p>El aviso aparecerá al entrar desde la fecha elegida.</p></div></div><label class="field">¿Qué quieres recordar?<textarea name="content" required rows="5" placeholder="Ej. Asegurarme de que la prueba se ha completado…"></textarea></label><label class="field">Fecha del recordatorio<input name="dueDate" type="date" min="'+todayKey()+'" required></label><button class="primary">＋ Guardar recordatorio</button></form><section class="reminder-board"><div class="reminder-board-head"><h2>Pendientes</h2><span>'+pending.length+' activos</span></div>'+(pending.length?'<div class="reminder-list">'+pending.map(reminderItem).join('')+'</div>':'<div class="reminder-empty"><div><b>✓ No tienes recordatorios pendientes</b><br><small>Crea uno cuando necesites volver a algo más adelante.</small></div></div>')+(done.length?'<h3 class="reminder-history-title">Completados</h3><div class="reminder-list">'+done.map(reminderItem).join('')+'</div>':'')+'</section></div>'}
    function renderPermanentNotes(){const all=(state.data.permanentNotes||[]).slice(),activeNotes=all.filter(x=>!x.archivedAt),archivedNotes=all.filter(x=>x.archivedAt),archived=state.noteArchiveTab==='archived',notes=(archived?archivedNotes:activeNotes).sort((a,b)=>String(archived?b.archivedAt:b.updatedAt).localeCompare(String(archived?a.archivedAt:a.updatedAt)));return '<div class="permanent-notes-layout"><form class="permanent-note-compose" id="permanent-note-form"><div class="reminder-section-title"><b>∞</b><div><h2>Nueva nota permanente</h2><p>Siempre visible, sin fecha y sin avisos.</p></div></div><p class="permanent-note-help"><b>◎</b><span>Guarda texto, documentos o ambas cosas. Si adjuntas un archivo, no necesitas escribir una anotación.</span></p><label class="field">Título <small>(opcional)</small><input name="title" maxlength="100" placeholder="Ej. Cosas que revisar cada semana"></label><label class="field">Anotación <small>(opcional si adjuntas un documento)</small><textarea name="content" maxlength="5000" rows="7" placeholder="Escribe una nota o déjala vacía si vas a adjuntar un archivo."></textarea></label>'+noteFileInput()+'<button class="primary">＋ Guardar nota permanente</button></form><section class="permanent-notes-board"><div class="permanent-notes-head"><div><h2>'+(archived?'Notas archivadas':'Mis notas permanentes')+'</h2><p>'+(archived?'Puedes consultar sus textos y documentos, restaurarlas o eliminarlas.':'Textos y documentos siempre disponibles para consultar.')+'</p></div><div class="note-archive-tabs"><button class="'+(!archived?'on':'')+'" data-note-archive-tab="active">Activas · '+activeNotes.length+'</button><button class="'+(archived?'on':'')+'" data-note-archive-tab="archived">Archivadas · '+archivedNotes.length+'</button></div></div>'+(notes.length?'<div class="permanent-note-grid">'+notes.map(permanentNoteCard).join('')+'</div>':'<div class="permanent-notes-empty"><div><b>'+(archived?'▣ No tienes notas archivadas':'∞ Tu espacio para lo que siempre importa')+'</b><small>'+(archived?'Cuando archives una nota permanente, aparecerá aquí.':'Guarda aquí información y documentos sin convertirlos en una tarea.')+'</small></div></div>')+'</section></div>'}
    function renderReminders(){const pendingCount=state.data.reminders.filter(r=>!r.isDone).length,noteCount=(state.data.permanentNotes||[]).filter(x=>!x.archivedAt).length;app.innerHTML='<header class="page-head"><div><small>TU AGENDA PERSONAL</small><h1>Recordatorios y notas</h1><p>Separa lo que debe avisarte de lo que quieres conservar siempre a mano.</p></div></header><nav class="reminder-tabs" aria-label="Tipo de recordatorio"><button class="'+(state.reminderTab==='dated'?'on':'')+'" data-reminder-tab="dated" aria-pressed="'+(state.reminderTab==='dated'?'true':'false')+'"><span class="reminder-tab-icon">◷</span><span class="reminder-tab-copy"><b>Recordatorios con fecha</b><small>Avisos para un día concreto</small></span><em>'+pendingCount+'</em></button><button class="'+(state.reminderTab==='permanent'?'on':'')+'" data-reminder-tab="permanent" aria-pressed="'+(state.reminderTab==='permanent'?'true':'false')+'"><span class="reminder-tab-icon">∞</span><span class="reminder-tab-copy"><b>Notas permanentes</b><small>Información siempre a mano</small></span><em>'+noteCount+'</em></button></nav>'+(state.reminderTab==='permanent'?renderPermanentNotes():renderDatedReminders());
      app.querySelectorAll('[data-reminder-tab]').forEach(b=>b.onclick=()=>{state.reminderTab=b.dataset.reminderTab;renderReminders();bind()});
      const reminderForm=app.querySelector('#reminder-form');if(reminderForm)reminderForm.onsubmit=async e=>{e.preventDefault();const button=reminderForm.querySelector('.primary'),fd=new FormData(reminderForm);button.disabled=true;button.textContent='Guardando…';if(await send({action:'save_reminder',content:fd.get('content'),dueDate:fd.get('dueDate')})){toast('Recordatorio guardado.');showDueReminders()}else{button.disabled=false;button.textContent='＋ Guardar recordatorio'}};
      const noteForm=app.querySelector('#permanent-note-form');if(noteForm){const button=noteForm.querySelector('.primary'),fileInput=noteForm.querySelector('input[type=file]');let submitting=false;noteForm.onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;button.disabled=true;button.textContent='Guardando…';const fd=new FormData(noteForm),saved=await savePermanentNoteWithFiles({action:'save_permanent_note',title:fd.get('title'),content:fd.get('content')},fileInput);if(saved){if(saved===true)toast('Nota permanente y documentos guardados.')}else{submitting=false;button.disabled=false;button.textContent='＋ Guardar nota permanente'}}}
      app.querySelectorAll('[data-complete-reminder]').forEach(b=>b.onclick=async()=>{if(await send({action:'complete_reminder',id:Number(b.dataset.completeReminder)})){toast('Recordatorio completado.');showDueReminders()}});app.querySelectorAll('[data-view-completed-reminder]').forEach(b=>b.onclick=()=>viewCompletedReminder(Number(b.dataset.viewCompletedReminder)));app.querySelectorAll('[data-view-permanent-note]').forEach(b=>b.onclick=()=>viewNote(Number(b.dataset.viewPermanentNote)));app.querySelectorAll('[data-edit-permanent-note]').forEach(b=>b.onclick=()=>permanentNoteEditor(Number(b.dataset.editPermanentNote)));app.querySelectorAll('[data-delete-permanent-note]').forEach(b=>b.onclick=()=>confirmDeletePermanentNote(Number(b.dataset.deletePermanentNote)));bindPermanentNoteArchive();
    }
