    const currentMonthKey=()=>todayKey().slice(0,7);
    const shiftMonth=(value,amount)=>{const match=String(value||'').match(/^(\\d{4})-(\\d{2})$/);if(!match)return currentMonthKey();const date=new Date(Number(match[1]),Number(match[2])-1+amount,1),pad=n=>String(n).padStart(2,'0');return date.getFullYear()+'-'+pad(date.getMonth()+1)};
    const monthLabel=value=>{if(!/^\\d{4}-\\d{2}$/.test(String(value||'')))return'';const date=new Date(value+'-01T12:00:00'),label=new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric'}).format(date);return label.charAt(0).toUpperCase()+label.slice(1)};
