      app.innerHTML=head(state.view==='active'?'Mis tickets':'Todos los tickets',state.view==='active'?'Todo lo que necesita tu atención, en un solo lugar.':state.data.tickets.length+' guardados · '+(state.data.tickets.length-active().length)+' completados')+
      '<section class="stats">'+stat(agendaActive().length,'Tickets activos','Pendientes de completar','purple','◆')+stat(progress,'En progreso','En los que estás trabajando','blue','↗')+stat(completed,'Terminados este mes','En estado Done desde el día 1','green','✓')+stat(cancelled,'Cancelados este mes','En estado Cancelled desde el día 1','red','×')+'</section>'+
      '<div class="toolbar"><label class="search">⌕<input id="search" placeholder="Buscar por clave, título o resumen…" value="'+esc(state.search)+'"></label><select id="status-filter"><option value="all">Todos los estados</option>'+state.data.statuses.map(s=>'<option value="'+s.id+'" '+(String(s.id)===String(state.status)?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select><select id="label-filter"><option value="all">Todas las labels</option>'+state.data.labels.map(l=>'<option value="'+l.id+'" '+(String(l.id)===String(state.label)?'selected':'')+'>'+esc(l.name)+'</option>').join('')+'</select><select id="attention-filter"><option value="all">Todos los llamadores</option><option value="none" '+(state.attention==='none'?'selected':'')+'>Sin llamador</option>'+state.data.attentionMarkers.map(x=>'<option value="'+x.id+'" '+(String(x.id)===String(state.attention)?'selected':'')+'>● '+esc(x.name)+'</option>').join('')+'</select>'+(state.view==='active'?'<button class="export-button" data-export-tickets>⇩ Exportar por mes</button>':'')+'<span>'+tickets.length+' tickets</span></div>'+
      (state.view==='active'?activeTicketMarkup:(hasTicketResults?table(otherTickets):emptyMarkup));
