      overlay.innerHTML='<div class="backdrop"><section class="modal" style="max-width:520px"><div class="modal-head"><div><b class="modal-icon">◌</b><span><h2>Añadir comentario</h2><p>'+esc(t.ticketKey)+' · '+esc(t.title)+'</p></span></div><button class="icon-btn" data-close>×</button></div><form id="quick-comment-form"><div class="form"><label class="field">Nuevo comentario<textarea name="content" rows="5" placeholder="Escribe una nota o actualización…"></textarea><small>La fecha y la hora se guardarán automáticamente.</small></label></div><div class="actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" disabled>Guardar comentario</button></div></form></section></div>';
