      let submitting=false;form.onsubmit=async e=>{e.preventDefault();const content=String(new FormData(form).get('content')||'').trim();if(!content||submitting)return;submitting=true;button.disabled=true;button.textContent='Guardando…';if(await send({action:'comment',ticketId:id,content})){overlay.innerHTML='';toast('Comentario guardado con su fecha y hora.')}else{submitting=false;button.disabled=false;button.textContent='Guardar comentario'}};
