    function commentTimeline(comments){return comments.length?comments.map(c=>'<article><i></i><div><div class="comment-meta"><small>Fecha y hora · '+fmt(c.createdAt,true)+'</small><span class="comment-actions"><button data-edit-comment="'+c.id+'" aria-label="Editar comentario">✎ Editar</button><button class="comment-remove" data-delete-comment="'+c.id+'" aria-label="Eliminar comentario">⌫ Eliminar</button></span></div><p>'+esc(c.content)+'</p></div></article>').join(''):'<p class="no-notes">Aún no hay comentarios. Añade el primero para empezar el seguimiento.</p>'}
