    await db.prepare("INSERT INTO attention_markers(name,color,position) SELECT ?,?,? WHERE NOT EXISTS (SELECT 1 FROM attention_markers WHERE lower(name)=lower(?))")
      .bind(name,markerColor,position,name).run();
