const SESSION_COOKIE = "mt_session";
const DEFAULT_USER = { email: "", name: "", password: "" }; // relleno local vía .dev.vars (no versionar secretos)

function bytesToB64(bytes) {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let bin = "";
  for (let i = 0; i < arr.length; i++) bin += String.fromCharCode(arr[i]);
  return btoa(bin);
}
function b64ToBytes(value) {
  const bin = atob(String(value || ""));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
function randomToken() {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  return [...bytes].map(b => b.toString(16).padStart(2, "0")).join("");
}
function timingSafeEqual(a, b) {
  const left = String(a || ""), right = String(b || "");
  const len = Math.max(left.length, right.length);
  let diff = left.length ^ right.length;
  for (let i = 0; i < len; i++) diff |= (left.charCodeAt(i) || 0) ^ (right.charCodeAt(i) || 0);
  return diff === 0;
}
async function hashPassword(password, saltB64) {
  const enc = new TextEncoder();
  const salt = saltB64 ? b64ToBytes(saltB64) : crypto.getRandomValues(new Uint8Array(16));
  const key = await crypto.subtle.importKey("raw", enc.encode(String(password)), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: 120000 }, key, 256);
  return { hash: bytesToB64(bits), salt: bytesToB64(salt) };
}
async function verifyPassword(password, hash, salt) {
  const next = await hashPassword(password, salt);
  return timingSafeEqual(next.hash, hash);
}
function cookieValue(request, name) {
  const header = request.headers.get("Cookie") || "";
  const parts = header.split(";");
  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed.startsWith(name + "=")) return decodeURIComponent(trimmed.slice(name.length + 1));
  }
  return "";
}
function sessionCookie(token, maxAge = 60 * 60 * 24 * 30) {
  const parts = [`${SESSION_COOKIE}=${encodeURIComponent(token)}`, "Path=/", "HttpOnly", "SameSite=Lax", `Max-Age=${maxAge}`];
  return parts.join("; ");
}
function clearSessionCookie() {
  return `${SESSION_COOKIE}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`;
}
function normalizeEmail(value) {
  return text(value).toLowerCase();
}
function validEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizeEmail(value));
}
function publicUser(row) {
  if (!row) return null;
  return { id: Number(row.id), email: String(row.email), name: String(row.name || ""), createdAt: row.createdAt || row.created_at || null };
}

async function addUserIdColumn(db, table) {
  const columns = (await db.prepare("PRAGMA table_info(" + table + ")").all()).results;
  if (!columns.some(column => column.name === "user_id")) {
    await db.prepare("ALTER TABLE " + table + " ADD COLUMN user_id INTEGER").run();
  }
}

async function seedWorkspace(db, userId) {
  const statusCount = await db.prepare("SELECT COUNT(*) total FROM statuses WHERE user_id=?").bind(userId).first();
  if (!Number(statusCount?.total)) {
    await db.batch(defaultStatuses.map(x => db.prepare("INSERT INTO statuses(name,color,is_done,position,user_id) VALUES(?,?,?,?,?)").bind(...x, userId)));
  }
}

async function createUser(db, { email, name, password, seed = true }) {
  const normalized = normalizeEmail(email);
  if (!validEmail(normalized)) throw new Error("Escribe un correo válido.");
  if (!text(name)) throw new Error("Escribe un nombre.");
  if (String(password || "").length < 6) throw new Error("La contraseña debe tener al menos 6 caracteres.");
  const existing = await db.prepare("SELECT id FROM users WHERE email=?").bind(normalized).first();
  if (existing) throw new Error("Ese correo ya está registrado.");
  const hashed = await hashPassword(password);
  const row = await db.prepare("INSERT INTO users(email,name,password_hash,password_salt) VALUES(?,?,?,?) RETURNING id,email,name,created_at createdAt")
    .bind(normalized, text(name).slice(0, 80), hashed.hash, hashed.salt).first();
  if (seed) await seedWorkspace(db, Number(row.id));
  return publicUser(row);
}

async function createSession(db, userId) {
  await db.prepare("DELETE FROM sessions WHERE expires_at < datetime('now')").run();
  const token = randomToken();
  await db.prepare("INSERT INTO sessions(user_id,token,expires_at) VALUES(?,?,datetime('now','+30 days'))").bind(userId, token).run();
  return token;
}

async function sessionUser(db, request) {
  const token = cookieValue(request, SESSION_COOKIE);
  if (!token) return null;
  await db.prepare("DELETE FROM sessions WHERE expires_at < datetime('now')").run();
  return db.prepare("SELECT u.id,u.email,u.name,u.created_at createdAt FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires_at >= datetime('now')")
    .bind(token).first();
}

async function migrateUsers(db) {
  const key = "users_v1";
  await db.batch([
    db.prepare("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)"),
    db.prepare("CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)"),
    db.prepare("CREATE INDEX IF NOT EXISTS idx_sessions_token ON sessions(token)"),
    db.prepare("CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at)"),
  ]);
  for (const table of ["statuses", "labels", "attention_markers", "tickets", "reminders", "permanent_notes", "standup_guides", "agenda_tasks", "billing_carryovers"]) {
    await addUserIdColumn(db, table);
  }
  const applied = await db.prepare("SELECT value FROM app_meta WHERE key=?").bind(key).first();
  let owner = await db.prepare("SELECT id FROM users WHERE email=?").bind(DEFAULT_USER.email).first();
  if (!owner) {
    const hashed = await hashPassword(DEFAULT_USER.password);
    owner = await db.prepare("INSERT INTO users(email,name,password_hash,password_salt) VALUES(?,?,?,?) RETURNING id")
      .bind(DEFAULT_USER.email, DEFAULT_USER.name, hashed.hash, hashed.salt).first();
  }
  const userId = Number(owner.id);
  if (applied?.value !== "done") {
    for (const table of ["statuses", "labels", "attention_markers", "tickets", "reminders", "permanent_notes", "standup_guides", "agenda_tasks", "billing_carryovers"]) {
      await db.prepare("UPDATE " + table + " SET user_id=? WHERE user_id IS NULL").bind(userId).run();
    }
    await db.prepare("INSERT OR REPLACE INTO app_meta(key,value) VALUES(?,?)").bind(key, "done").run();
  }
  await seedWorkspace(db, userId);
}

async function migrateAgendaTaskComments(db){const key="agenda_task_comments_v1",done=await db.prepare("SELECT value FROM app_meta WHERE key=?").bind(key).first();if(done?.value==="done")return;await db.prepare("CREATE TABLE IF NOT EXISTS agenda_task_comments (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL, subtask_id INTEGER NOT NULL DEFAULT 0, content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)").run();await db.prepare("CREATE INDEX IF NOT EXISTS idx_agenda_task_comments_target ON agenda_task_comments(task_id,subtask_id,created_at,id)").run();await db.prepare("PRAGMA optimize").run();await db.prepare("INSERT OR REPLACE INTO app_meta(key,value) VALUES(?,?)").bind(key,"done").run()}

